arguments.file_text:
namespace sv_9f41da717313480e8d051a9d47b72987.Services;

/// <summary>
/// Represents the currently selected warehouse.
/// Used as the cascading value type across all render modes.
/// </summary>
public class WarehouseState
{
    public string WarehouseId { get; set; } = "WH-001";
    public string WarehouseName { get; set; } = "Warehouse A";

    public static readonly (string Id, string Name)[] AvailableWarehouses =
    [
        ("WH-001", "Warehouse A"),
        ("WH-002", "Warehouse B"),
        ("WH-003", "Warehouse C"),
        ("WH-004", "Warehouse D"),
    ];
}

namespace sv_9f41da717313480e8d051a9d47b72987.Services;

/// <summary>
/// Scoped service (per-circuit) that polls for low-stock alerts and notifies
/// all subscribed components when data changes. Each user circuit gets its
/// own independent instance, so warehouse selections don't leak between users.
