using Microsoft.AspNetCore.Components;
using sv_9f41da717313480e8d051a9d47b72987.Components;
using sv_9f41da717313480e8d051a9d47b72987.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Warehouse state as a cascading value — crosses render mode boundaries.
// Each circuit gets its own CascadingValueSource because this lambda runs
// per-scope (scoped DI), ensuring per-user isolation.
builder.Services.AddCascadingValue(sp =>
{
    var state = new WarehouseState();
    return new CascadingValueSource<WarehouseState>(state, isFixed: false);
});

// Scoped: each circuit (user) gets its own alert service with independent polling.
builder.Services.AddScoped<InventoryAlertService>();

