@* Interactive warehouse selector for the top bar.
   Must be interactive so it can handle change events from the static layout. *@
@rendermode InteractiveServer
@inject CascadingValueSource<WarehouseState> WarehouseSource
@inject InventoryAlertService AlertService
@using sv_9f41da717313480e8d051a9d47b72987.Services

<div class="d-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold" for="warehouseSelect">Warehouse:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="width: auto;"
            value="@_selectedId"
            @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in WarehouseState.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    private string _selectedId = "WH-001";

    protected override void OnParametersSet()
    {
        if (Warehouse is not null)
        {
            _selectedId = Warehouse.WarehouseId;
        }
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString() ?? "WH-001";
        var match = WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == newId);

        var updated = new WarehouseState
        {
            WarehouseId = match.Id ?? newId,
            WarehouseName = match.Name ?? newId
        };

        _selectedId = updated.WarehouseId;

        // Push to all [CascadingParameter] subscribers across render modes.
        await WarehouseSource.NotifyChangedAsync(updated);

        // Restart polling for the new warehouse so alert counts update immediately.
        AlertService.RestartPolling(updated.WarehouseId);
    }
}

@* Reusable alert badge that subscribes to InventoryAlertService events.
   Can be placed anywhere — sidebar, dashboard, toolbar — and stays in sync
   with all other AlertBadge instances via the shared scoped service. *@
