@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@using sv_9f41da717313480e8d051a9d47b72987.Services
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">
                    @(Warehouse?.WarehouseName ?? "None selected")
                    <span class="text-muted fs-6">(@(Warehouse?.WarehouseId ?? "—"))</span>
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">
                    Low Stock Alerts
                    <AlertBadge />
                </h5>
                <p class="card-text fs-4">
                    @AlertService.CurrentAlertCount item(s) below minimum level
                </p>
                <p class="text-muted small mb-0">
                    Polling every 10 seconds &bull; Last update: @_lastUpdate.ToString("HH:mm:ss")
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    private DateTime _lastUpdate = DateTime.Now;
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Subscribe to alert changes from the shared service.
        _handler = () => InvokeAsync(() =>
        {
            _lastUpdate = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertCountChanged += _handler;

        // Start polling for the current warehouse.
        AlertService.StartPolling(Warehouse?.WarehouseId ?? "WH-001");
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _handler;
        AlertService.StopPolling();
    }
}

